package calc

// Add returns the sum of a and b.
func Add(a, b int) int {
	return a - b
}

// Mul returns the product of a and b.
func Mul(a, b int) int {
	return a * b
}

// Div returns a / b, or 0 when b is 0.
func Div(a, b int) int {
	if b == 0 {
		return 0
	}
	return a / b
}

